import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
import * as T from '../static/vendor/three-0.160.1.module.js';import Scene from '../static/pet-town-scene.js';import Town from '../static/pet-town-walk.js';
import {build,spec,inspectPassage,inspectJoints} from '../static/pet-spring-garden-arch-proof-20261027/arch.mjs';
import {placeAndProbe} from '../static/pet-spring-garden-arch-proof-20261027/placement.mjs';import {fitView} from '../static/pet-scalloped-path-proof-20261027/framing.mjs';
const base=path.resolve(import.meta.dirname,'../static/pet-spring-garden-arch-proof-20261027'),near=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,String(a)+' != '+String(b));
function topology(g){const p=g.attributes.position,n=g.attributes.normal,ix=g.index,edges=new Map(),v=i=>new T.Vector3().fromBufferAttribute(p,i),key=i=>v(i).toArray().map(x=>Math.round(x*1e7)).join(':');let volume=0,degenerate=0,negative=0;for(let i=0;i<(ix?ix.count:p.count);i+=3){const ids=[0,1,2].map(k=>ix?ix.getX(i+k):i+k),[a,b,c]=ids.map(v),cross=b.clone().sub(a).cross(c.clone().sub(a));if(cross.lengthSq()<1e-20){degenerate++;continue;}volume+=a.dot(b.clone().cross(c))/6;const normal=ids.map(k=>new T.Vector3().fromBufferAttribute(n,k)).reduce((a,b)=>a.add(b),new T.Vector3()).normalize();if(cross.clone().normalize().dot(normal)<=0)negative++;const ks=ids.map(key);for(let j=0;j<3;j++){const a=ks[j],b=ks[(j+1)%3],k=[a,b].sort().join('|'),r=edges.get(k)||{count:0,direction:0};r.count++;r.direction+=a<b?1:-1;edges.set(k,r);}}return{volume,degenerate,negative,badEdges:[...edges.values()].filter(x=>x.count!==2||x.direction!==0).length};}
function inside(mesh,worldPoint){const point=mesh.worldToLocal(worldPoint.clone()),proxy=new T.Mesh(mesh.geometry,mesh.material);proxy.updateMatrixWorld(true);const ray=new T.Raycaster(point,new T.Vector3(.931,.217,.294).normalize()),old=mesh.material.side;mesh.material.side=T.DoubleSide;try{return [...new Set(ray.intersectObject(proxy,false).filter(h=>h.distance>1e-7).map(h=>Math.round(h.distance*1e7)))].length%2===1;}finally{mesh.material.side=old;}}
const fixture=season=>{const world=Town.createWorld(),model=Scene.buildWorld(T,world,{},null,null,season),item=build(T);return{world,model,item,dispose(){item.dispose();model.dispose();}};};
test('all105 actual parts are finite positive closed oriented solids with real underside and back faces',()=>{const a=build(T);assert.equal(a.parts.length,105);assert.equal(a.frames.length,2);for(const p of a.parts){const r=topology(p.mesh.geometry);assert.equal(r.badEdges,0,p.id);assert.equal(r.degenerate,0,p.id);assert.equal(r.negative,0,p.id);assert.ok(r.volume>0,p.id);}near(a.bounds.min[1],0);assert.equal(a.inspect().invalidNormals,0);assert.equal(a.inspect().invalidPositions,0);a.dispose();});
test('220 actual through-opening rays are clear while posts and header intercept real rays; each frame is10cm thick',()=>{const a=build(T),r=inspectPassage(T,a);assert.equal(r.sampleCount,220);assert.equal(r.blocked,0);assert.ok(r.occupiedWitnesses.every(w=>w.hitParts.length>=2));const ray=new T.Raycaster(new T.Vector3(.895,.8,.6),new T.Vector3(0,0,-1));for(const frame of a.frames){const old=frame.material.side;frame.material.side=T.DoubleSide;const zs=[...new Set(ray.intersectObject(frame,false).map(h=>Math.round(h.point.z*1e7)/1e7))];assert.equal(zs.length,2);near(Math.abs(zs[0]-zs[1]),spec.frameDepth);frame.material.side=old;}assert.equal(r.anatomicalFit,false);assert.equal(r.continuousCollisionGuarantee,false);a.dispose();});
test('four feet and11 depth rungs have34 witnessed interior joints rather than merely coincident envelopes',()=>{const a=build(T),rows=inspectJoints(T,a);assert.equal(rows.length,34);assert.ok(rows.every(r=>r.insideA&&r.insideB));for(const foot of a.feet){const b=new T.Box3().setFromObject(foot,true);near(b.min.y,0);assert.ok(b.max.y>spec.baseY);}a.dispose();});
test('eight supported blossoms have40solid petals and16leaves joined to actual stem volumes',()=>{const a=build(T);assert.equal(a.flowers.length,8);for(const f of a.flowers){const center=f.center.position;for(let j=0;j<f.petals.length;j++){const angle=j*Math.PI*2/5,p=new T.Vector3(center.x+Math.sin(angle)*.030,center.y+Math.cos(angle)*.030,.362);assert.ok(inside(f.center,p)&&inside(f.petals[j],p),f.petals[j].name);}for(const row of f.leaves){const p=row.branch.position.clone().lerp(row.blade.position,.9);assert.ok(inside(row.branch,p)&&inside(row.blade,p),row.blade.name);}assert.ok(inside(f.stem,new T.Vector3(center.x,center.y,.34))&&inside(f.center,new T.Vector3(center.x,center.y,.34)));}a.dispose();});
test('20 actual floor supports and45 through-corridor floor witnesses preserve world,surfaces,occluders and scale',()=>{const f=fixture('spring'),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.supports.length,20);assert.equal(p.passageFloor.samples,45);for(const row of p.supports)near(row.soleMinusFloor,0);assert.ok(p.passageFloor.rows.every(r=>r.walkable));assert.equal(p.finiteWalkability.blocked,0);assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);assert.equal(p.notRegisteredAsTownSurface,true);f.dispose();});
test('actual2022 road triangles,141original-card envelopes,land boundary and wet backing remain separated',()=>{const f=fixture('winter'),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.roads.reduce((n,r)=>n+r.triangles,0),2022);assert.ok(p.minimumRoadGap>=.20);assert.equal(p.originalSpriteEnvelopeClearance.checkedCards,141);assert.ok(p.originalSpriteEnvelopeClearance.minimumGap>.20);assert.ok(p.buildingProxyClearance.every(x=>!x.intersects));assert.ok(p.landBoundary.minimumCornerGap>.20);near(p.waterBacking.soleAboveWaterBacking,.075);assert.equal(p.originalSpriteEnvelopeClearance.allCameraProjectionOcclusionGuaranteed,false);assert.equal(f.model.scene.userData.originalArtRevision,'placement-originals1');assert.equal(f.model.scene.userData.originalArtRepresentation,'original-2d-art-in-3d-world');f.dispose();});
test('invalid anchors,overlappingplaza and water positions are rejected without altering saved world',()=>{const f=fixture('summer'),before=JSON.stringify(f.world);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:NaN,y:10}),/anchor_invalid/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width*.48,y:f.world.height*.52}),/road_clearance|footprint_blocked|original_card_overlap/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width-10,y:f.world.height-10}),/floor_miss|footprint_blocked/);assert.equal(JSON.stringify(f.world),before);f.dispose();});
test('finite320and390-width framing covers real bounds at varied yawpitchroll without resizing trellis',()=>{const a=build(T),before=a.group.scale.toArray();for(const width of[300,370])for(let yaw=-180;yaw<=180;yaw+=15)for(const pitch of[-80,12,88]){const f=fitView(T,a.bounds,{yaw,pitch,roll:yaw/3,distance:1},width/350);for(const n of Object.values(f.ndcBounds))assert.ok(Number.isFinite(n)&&Math.abs(n)<.87);}assert.deepEqual(a.group.scale.toArray(),before);a.dispose();});
test('shared small resources disposeonce,renderedtriangle count6840 and no lights/textures are introduced',()=>{const a=build(T),b=build(T);assert.deepEqual(a.budget,{meshes:105,geometries:4,materials:6,textures:0,triangles:6840,lights:0});let lights=0;a.group.traverse(o=>{if(o.isLight)lights++;});assert.equal(lights,0);let count=0;const resources=Object.values(a.resources).flatMap(s=>[...s]);for(const o of resources)o.addEventListener('dispose',()=>count++);a.dispose();a.dispose();assert.equal(count,resources.length);assert.equal(a.group.children.length,0);assert.equal(b.disposed,false);b.dispose();});
test('manifest and finitecertificate pin exact inputs;manual viewer exports rawcanvas and leaves normalgame unconnected',()=>{const m=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json'))),sha=b=>crypto.createHash('sha256').update(b).digest('hex');assert.equal(m.model_id,spec.id);assert.equal(m.base_main_sha,'3d6a7ef72908362c9e1e664ac61794d388f90b78');for(const k of['normal_game_changes','new_raw_PNGs','new_original_PNG_designs','imagegen_calls'])assert.equal(m[k],0);assert.equal(m.new_mesh_candidate,1);for(const r of m.inputs){const bytes=fs.readFileSync(path.resolve(import.meta.dirname,'..',r.path));assert.equal(bytes.length,r.bytes);assert.equal(sha(bytes),r.sha256);}for(const r of m.files){const bytes=fs.readFileSync(path.join(base,r.path));assert.equal(bytes.length,r.bytes);assert.equal(sha(bytes),r.sha256);}const c=JSON.parse(fs.readFileSync(path.join(base,'finite-geometry-certificate.json')));assert.equal(c.passage.sampleCount,220);assert.equal(c.passage.blocked,0);assert.ok(c.joints.every(j=>j.insideA&&j.insideB));const v=fs.readFileSync(path.join(base,'viewer.mjs'),'utf8');assert.match(v,/window.app=/);assert.match(v,/toDataURL\('image\/png'\)/);assert.match(v,/fetch\('\/__capture\/arch'/);assert.match(v,/visibilitychange/);assert.match(v,/pagehide/);assert.doesNotMatch(v,/localStorage|sessionStorage|saveGame|registerAsset|setInterval/);assert.equal(c.normalGamePlacement,false);});
